const fs = require('fs');

function base(k, l) {
    let sum = 0;
    while (k !== 0) {
        sum += k % l;
        k = Math.floor(k / l);
    }
    return sum;
}

function gcd(a, b) {
    return b === 0 ? a : gcd(b, a % b);
}

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
const n = parseInt(input[0], 10);

let f = 0;
for (let i = 2; i < n; i++) {
    f += base(n, i);
}

const j = gcd(f, n - 2);
console.log(`${f / j}/${(n - 2) / j}`);

